window.__rgjB=null; window.__rgjErr=null;
(async () => { try {
  const want = ["Tetris", "Dr. Mario", "Yoshi's Cookie", "Wario's Woods", "Kickle Cubicle", "Adventures of Lolo", "Adventures of Lolo 2", "Adventures of Lolo 3", "Klax", "Pipe Dream", "Puzznic", "Solomon's Key", "Fire 'n Ice", "Bomberman", "Bomberman II", "Q*bert", "Yoshi", "Mendel Palace", "Boulder Dash", "Columns"];
  const norm = s => String(s).toLowerCase().replace(/&amp;/g,'&').replace(/[^a-z0-9]+/g,' ').trim();
  const findAch = (n,d) => { if(!n||typeof n!=='object'||d>8) return null;
    if (Array.isArray(n)&&n.length&&n[0]&&typeof n[0]==='object'&&'title' in n[0]&&'points' in n[0]) return n;
    for (const k in n){ const r=findAch(n[k],d+1); if(r) return r; } return null; };
  const pick = (rows) => {
    const r = rows.filter(a => Number(a.points) > 0 && Number(a.ratio) >= 0)
                  .sort((a,b)=> a.ratio-b.ratio || a.points-b.points || a.id-b.id);
    if (!r.length) return [];
    if (r.length <= 3) return r.map((x,i)=>({...x, tier: ['easy','intermediate','advanced'][i]}));
    const easy=r[0], hard=r[r.length-1];
    const mid=Math.sqrt(Math.max(easy.ratio,1)*Math.max(hard.ratio,1));
    let m=r[1];
    for (const x of r.slice(1,-1)) if (Math.abs(Math.log(Math.max(x.ratio,1))-Math.log(mid)) < Math.abs(Math.log(Math.max(m.ratio,1))-Math.log(mid))) m=x;
    return [{...easy,tier:'easy'},{...m,tier:'intermediate'},{...hard,tier:'advanced'}];
  };
  const out = {};
  for (const t of want) {
    const nx = norm(t);
    let hit = null;
    try {
      const res = await fetch('https://retroachievements.org/internal-api/search?q='+encodeURIComponent(t)+'&scope=games');
      const j = await res.json();
      const games = (j.results && j.results.games) || [];
      hit = games.find(g => g.system && g.system.id === 7 && norm(g.title) === nx)
         || games.find(g => g.system && g.system.id === 7 && (norm(g.title).startsWith(nx) || nx.startsWith(norm(g.title))));
    } catch(e) { out[t] = { error: 'search: '+String(e.message) }; continue; }
    if (!hit) { out[t] = { unmatched: true, picks: [] }; continue; }
    try {
      const h = await (await fetch('https://retroachievements.org/game/'+hit.id)).text();
      const d2 = new DOMParser().parseFromString(h,'text/html');
      const blob = d2.querySelector('script[type="application/json"]');
      const j2 = JSON.parse(blob.textContent);
      const arr = findAch(j2,0) || [];
      const rows = arr.map(a => ({ id:a.id, title:a.title, desc:a.description||'', points:Number(a.points)||0,
                                   ratio:Number(a.pointsWeighted)||Number(a.points)||0, type:a.type||'' }));
      out[t] = { raId: hit.id, raTitle: hit.title, n: rows.length, picks: pick(rows), unmatched: false };
    } catch(e) { out[t] = { raId: hit.id, raTitle: hit.title, error: 'game: '+String(e.message), picks: [] }; }
    await new Promise(r=>setTimeout(r,120));
  }
  window.__rgjB = JSON.stringify(out);
} catch(e){ window.__rgjErr = String(e && e.stack || e); } })();
